# FILE: scripts/build_ledger_page.py
# ROLE: [U-19 · D-13] docs/agrodss_backlog.md → 발행용 작업대장 페이지(HTML 조각 — 발행 도구가 doctype/head/body 를 씌운다).
#   읽기 전용 — 저장소에는 아무것도 쓰지 않는다. 출력은 인자로 준 파일 하나뿐.
#   [2026-09-27] 이 생성기가 세션 스크래치패드에만 있었다(U-35 · prewalk_grid 와 같은 형태 — 세션이 끝나면 사라진다). 저장소로 옮기며 옛 회차의
#   BEST 스물여덟 개를 잘라냈다(그 서술은 핸드오버 표와 대장 로그가 대신한다). 회차마다 다시 쓰는 것 셋: BEST(발행자 형식 — 할 것 하나 · 한 것 · 막힌 것, check_best 가 강제) · NEXT_PUBLISHER · NEXT_SESSION.
#   쓰는 법   python scripts/build_ledger_page.py <출력.html>   → 폭 넷 넘침은 node scripts/browser/static_overflow.cjs <출력.html>
#   래칫     머리에 커밋 해시는 하나까지(U-19) · 페이지에 모델 식별자 0 · 지번 주소 패턴 0(PII) — 쓰기 전에 단언한다
import html
import re
import subprocess
import sys
from datetime import date as _date, timedelta as _timedelta
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
from frontend import render  # noqa: E402


# ── 흐르는 날수는 **생성기가 센다** ──────────────────────────────────────────────────
# [2026-10-06 실측] 이 파일의 ②b 줄은 이미 *"날수를 여기 적지 않습니다 — 날마다 변하는 숫자를 안내에 박으면 하루 뒤 거짓이 됩니다"* 라고 적고 있었다.
# 그런데 **BEST 블록이 그 규율을 어기고** 「10/7 부터(이틀 뒤)」 라고 손으로 적어 두었고, 날이 바뀌자 그대로 거짓이 됐다(이틀 → 하루).
# 규율이 한 자리(②b)에만 닿아 있던 §7.5 지점 축이다. 그래서 상대 날수는 글이 아니라 **계산**이고, 날짜도 정본(격자 · 결정 params)에서 센다.
def today() -> _date:
    """생성 시점의 오늘 — 화면 정본과 같은 길(AGRODSS_TODAY 고정을 따른다)."""
    from frontend import config
    return config.today()


def when(day: _date, word: str = "부터") -> str:
    """「10/7 부터(내일)」 — 절대 날짜가 먼저, 상대 말은 괄호에. 날짜와 조사 사이를 바꾸면 안내 래칫(test_leaf_harvest_alert_lead)이 먼저 터진다."""
    n = (day - today()).days
    rel = {0: "오늘", 1: "내일", 2: "모레"}.get(n) or (f"{n}일 뒤" if n > 0 else f"{-n}일 전")
    return f"{day.month}/{day.day} {word}({rel})"


# ── 세는 수도 **생성기가 센다** ────────────────────────────────────────────────────
# [낡음 대조 2026-10-06] 날수를 고친 그 규율의 **건수 판**이다. 이 목록은 「화면의 15줄 · 답 0」 · 「기대 종류 열넷」 · 「답 없는 줄 14」 처럼
# 정본에서 셀 수 있는 수를 손으로 적고 있었다. 날짜와 달리 아직 거짓은 아니었지만(오늘 재니 15 · 14 · 6/20 전부 맞았다) 바뀌는 날 조용히 거짓이 된다 —
# 그리고 더 나쁜 것이 하나 섞여 있었다: 「답 0」 은 **세션이 못 보는 수**(답은 발행자 PC 덮개에만 있다)인데 잰 수처럼 적혀 있었다(못 잼 ≠ 0).
def decisions_count() -> dict[str, int]:
    """결정 화면의 셈 — 남은 것 · 결정됨 · 전체(정본에서). 답한 수는 **세션이 못 센다**(그 PC 덮개)."""
    from ingest import decisions
    return {"total": len(decisions.IDS), "decided": len(decisions.DECIDED),
            "open": len(decisions.IDS) - len(decisions.DECIDED)}


def probe_count() -> dict[str, int]:
    """문장 형태 점검 — 전체 줄 · 기대가 붙은 줄 · 남은 줄(발행자가 붙일 것)."""
    import json
    doc = json.loads((ROOT / "data" / "utterance_probes.json").read_text(encoding="utf-8"))
    rows = [r for g in doc["groups"] for r in g["rows"]]
    exp = [r for r in rows if r.get("expected")]
    return {"total": len(rows), "expected": len(exp), "left": len(rows) - len(exp)}


def _unit() -> tuple[dict, dict]:
    """첫 밭(쪽파 가을)의 재배 단위와 그 재배 달력 — 읽는 자리는 정본 하나(grid.schema.load_unit)."""
    from grid import schema as grid_schema
    from ingest import subjects
    s = subjects.by_id("p001-jjokpa-2026f")
    unit, miss = grid_schema.load_unit(s)
    assert unit and not miss, miss
    return s, unit


def _harvest(unit: dict) -> dict:
    return next(st for st in unit["stages"] if str(st.get("name", "")).strip() == "수확")


def harvest_window_start() -> _date:
    """수확 창이 열리는 날 — 격자(심은 날 + from_day)에서 센다."""
    s, unit = _unit()
    return _date.fromisoformat(s["anchor"]) + _timedelta(days=int(_harvest(unit)["window"]["from_day"]))


def harvest_window_end() -> _date:
    """수확 창이 닫히는 날(그 날까지 창 안) — 격자(심은 날 + to_day)에서 센다. [앞날 걷기 W-20 · 2026-10-14] 창이 닫힌 뒤에도 페이지가
    「잎 기준 경보 둘 · 매일 · 주의」 라고 했다(실측: 11-04 부터 「경보 수확 지연」 하나) — 닫히는 날을 알아야 그 뒤의 말을 고를 수 있다."""
    s, unit = _unit()
    return _date.fromisoformat(s["anchor"]) + _timedelta(days=int(_harvest(unit)["window"]["to_day"]))


def stage_today() -> str:
    """답이 읽는 오늘 칸 — 「전」(수확 칸 앞) · 「수확」 · 「후」(수확 뒤 칸) · 「밖」(재배 달력 끝 뒤). 경계일은 앞 칸이다(grid.capture.stage_for_day 정본).
    [재검토 L1 · 2026-10-14] 수확 창(_PHASE)은 **경보 문장**의 축이다(위험 경보는 창으로 센다). 자재 · 가뭄 · 촬영 · 위험 답은 칸으로 센다 —
    창이 열리는 날(50일째)에 그 답들은 아직 생육 중기 칸이었는데 페이지는 그 날 수확 칸 답을 인용했다."""
    from grid import capture
    s, unit = _unit()
    day = (today() - _date.fromisoformat(s["anchor"])).days
    st = capture.stage_for_day(unit, day)
    if st is None:
        return "전" if day < 0 else "밖"
    h = int(_harvest(unit)["order"])
    return "전" if int(st["order"]) < h else ("수확" if int(st["order"]) == h else "후")


def harvest_stage_from() -> _date:
    """답이 수확 칸을 읽기 시작하는 날 — 창이 열리는 날은 경계일이라 앞 칸이다(그래서 보통 창 + 1일). 격자와 칸 정본에서 센다."""
    from grid import capture
    s, unit = _unit()
    h = _harvest(unit)
    w = h["window"]
    day = next(d for d in range(int(w["from_day"]), int(w["to_day"]) + 1)
               if (capture.stage_for_day(unit, d) or {}).get("order") == h["order"])
    return _date.fromisoformat(s["anchor"]) + _timedelta(days=day)


def stage_in_scope(order: int) -> bool:
    """그 칸을 위험 경보가 오늘 보는가 — 칸이 열려 있거나 horizon 안에 열린다(judge.risk_alert 의 범위와 같은 셈: from_day − horizon ≤ 오늘 ≤ to_day).
    칸으로 잘라 낸 카드(배수 경보 = 칸 4)는 이 범위 밖이면 「해당 없음」 이라 어떤 값도 안 읽는다."""
    s, unit = _unit()
    st = next(x for x in unit["stages"] if int(x["order"]) == int(order))
    day = (today() - _date.fromisoformat(s["anchor"])).days
    return int(st["window"]["from_day"]) - horizon() <= day <= int(st["window"]["to_day"])


def wet_now() -> tuple[tuple[str, ...], _date, str]:
    """과습 위험 — (오늘 위험 경보가 보는 과습 칸 이름들, 이번 작기의 마지막 과습 칸이 끝나는 날, 그 칸 이름).
    배수 값을 읽는 판단(위험 경보의 과습 근거 · 배수 경보)은 과습 칸을 볼 때만 그 값을 읽는다. 과습 위험인지는 판정기 정본(judge.risk_alert._is_wet_risk)이 가른다.
    [재검토 L3 · R2 · 2026-10-14] 페이지가 날마다 「과습 경보는 그대로」 · 「과습 근거가 배수 값을 읽는다」 고 했다 — 실측: 생육 중기 칸이 닫힌
    다음 날(10-15)부터 과습 경보도, 배수 값을 읽는 판단도 없다(배수를 나쁨 → 좋음으로 바꿔도 봉투가 한 글자도 안 바뀐다).
    [재재검토] 첫 판은 끝(마지막 과습 칸의 to_day)만 봤다 — 시작(from_day − horizon)이 없었고, 과습 위험은 칸 1(종구 부패)에도 있다. 칸마다 범위로 센다.
    [남은 것 · 등재급] 용도(by_use)로만 들어오는 과습 위험은 여기서 안 보인다 — 용도 값은 발행자 PC 에만 있고 지금 by_use 값은 비어 있다(D-24 가 오면 함께)."""
    from grid import schema as grid_schema
    from judge import risk_alert
    s, unit = _unit()
    wet = [st for st in unit["stages"] if isinstance(st.get("risks"), list) and any(risk_alert._is_wet_risk(r) for r in st["risks"])]
    assert wet, "과습 위험이 든 칸이 없다 — 배수 문장을 고를 근거가 없다"
    live = tuple(str(st["name"]) for st in wet if stage_in_scope(int(st["order"])))
    end = grid_schema.last_day({"stages": wet})          # 칸들의 마지막 날 — 셈은 정본 한 곳(달력 끝과 같은 함수 · 여기서 max 를 또 돌지 않는다)
    name = next(st["name"] for st in wet if int(st["window"]["to_day"]) == end)
    return live, _date.fromisoformat(s["anchor"]) + _timedelta(days=int(end)), str(name)


def horizon() -> int:
    """위험 경보가 다음 칸을 미리 보는 날수 — 결정 params 정본에서 읽는다(안내에 7 을 박지 않는다)."""
    from judge import registry, risk_alert, stage_decisions  # noqa: F401 — 등록부 적재(결정 params 를 읽으려면 필요)
    return int(registry.get(risk_alert.DECISION_ID).params["horizon_days"])


def alert_start() -> _date:
    """잎 수확 기준 경보가 서는 첫날 = **수확 창 − horizon**. 날짜를 박지 않고 정본에서 센다(격자나 horizon 이 바뀌면 안내가 함께 움직인다)."""
    return harvest_window_start() - _timedelta(days=horizon())


def md(day: _date) -> str:
    """「10/7」 — 괄호 없는 절대 날짜(범위 · 이미 지난 기록에). 상대 말이 필요하면 `when`."""
    return f"{day.month}/{day.day}"


def field_card(field: str, value: str) -> dict[str, str]:
    """밭 정보 카드의 **화면 글자** — 카드 머리(「용도 → 종구 생산」 · 「배수 → 좋음」)와 단추 이름을 정본에서 읽는다(chat_pages._draft_html 과 같은 낱말 표).

    [앞날 걷기 2026-10-13] 이 페이지가 발행자의 10/14 한 수를 「「밭 정보 → 종구 생산」 카드가 섭니다 → '일지에 넣기'」 로 적고 있었다. 그 카드의 단추는
    「밭 정보에 넣기」 이고(2026-10-04 에 이름이 바뀌었다) 화면의 '일지에 넣기' 는 **방금 보낸 그 한 줄(본 것)** 의 단추다 — 안내대로 누르면 그 말이 일지에
    들어가고 용도는 빈 채로 남는다(그러면 10/14 부터 잎 기준 경보 둘이 「주의」 로 나간다 — 막으려던 바로 그것). 카드 머리도 「밭 정보 →」 가 아니라 「용도 →」 다.
    채팅은 바른 말을 하고 있었다(PLACE_SAID · card_line) — 이 페이지만 정본에서 안 읽고 손으로 적었다(§7.5 지점 · 화면 이름 계약은 메뉴 이름만 보고 단추 이름은 안 봤다).
    처방 직후 전수: 같은 페이지에 같은 꼴이 둘 더 있었다(배수 카드를 「밭 정보 → 배수 좋음」 · 「밭 정보 → 좋음」 으로 — 화면은 「배수 → 좋음」)."""
    from ingest import chat, parcels
    # [검토 2026-10-13] 「카드가 안 보이면 아무 말이나 한 줄 보내면 섭니다」 는 카드가 **이미 서 있는** 상태(발행자 PC — 옛 메시지 아래)에서는 거짓이다 — 같은 카드는
    # 다시 안 세운다(send 가 기다리는 카드를 거른다). 셈 줄이 이제 자리마다 세므로(「… 밭 정보 2」) 그 줄로 가른다 — 줄 이름 · 자리 이름도 정본에서
    find = (f"화면의 「{chat.PENDING_LABEL}」 줄에 「{chat.place_noun('parcel.field')}」 가 세어져 있으면 카드가 이미 대화 위쪽에 서 있습니다 · "
            "없으면 아무 말이나 한 줄 보내면 섭니다")
    return {"head": f"{parcels.FIELD_WORDS[field]} → {value}", "button": chat.confirm_label("parcel.field"), "find": find}

text = (ROOT / "docs" / "agrodss_backlog.md").read_text(encoding="utf-8")
head = subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT, capture_output=True,
                      encoding="utf-8", errors="replace").stdout.strip()
counts = render.ledger_counts(text)
ids = re.findall(r"^\| ([DIMUR]-\d+) \|", text, re.M)
# [앞날 걷기 F36 · 2026-10-14] 머리의 「항목 N」 과 상태 알약의 합이 갈렸다(96 · 92) — 상태 셀을 못 읽은 행은 **말없이** 빠졌다. 갈리면 생성기가 멈춘다
assert sum(counts.values()) == len(ids), f"상태를 못 읽은 대장 행이 있다 — 항목 {len(ids)} · 알약 합 {sum(counts.values())} (상태 말은 {' · '.join(render.STATES)})"
body = render.md_to_html(text)
# 첫 h1 은 페이지 헤더가 대신한다
body = re.sub(r"^<h1>.*?</h1>\s*", "", body, count=1, flags=re.S)

_DEC, _PROBE = decisions_count(), probe_count()      # 손으로 적지 않는다 — 정본에서 센다(아래 문면이 이 값을 쓴다)
from scripts.verify_claims import CLAIMS_MIN as _CLAIMS_MIN  # noqa: E402  [앞날 걷기 F35] 보고 확인의 줄 수 하한 — 손으로 「46」 이라 적었다(정본은 그 도구)
from ingest import decisions as _decisions  # noqa: E402
# [앞날 걷기 F38 · 2026-10-14] ⓪⁺ 가 「다섯 항목이 그 답에 매달린다」 — 결정 D-2 는 넷(D-3 · D-7 · D-19 · M-11)을 적어 놓고 「다섯」 이라 했다. 적힌 것에서 센다
# [앞날 걷기 F37 · 2026-10-14] ⓪ᵉ 가 「놓침 열두 가지」 를 손으로 적었다 — 용도에 「종구 생산」 이 들어가면 여덟이다(조건을 뗀 수). 두 수를 조건과 함께 둔다 —
# 측정 2026-10-14 · 기록이 없는 격리 사본 · 달력 끝 다음 날. 판정(plan_vs_actual)이 바뀌면 tests/test_ledger_page_own_counts.py 가 다시 재서 붉다
_MISSED_END = {"잎": 12, "종구": 8}
_D2_HANG = len(re.findall(r"\b[DMU]-\d+\b", next(i for i in _decisions.ITEMS if i["id"] == "D-2")["unblocks"]))
_ALERT_FROM, _WINDOW_OPEN, _HORIZON = alert_start(), harvest_window_start(), horizon()      # 손으로 적지 않는다 — 격자(수확 창)와 결정(horizon)에서 센다
_WINDOW_END = harvest_window_end()
# [앞날 걷기 W-20 · 2026-10-14] 페이지는 날마다 만들어진다 — 수확 창 앞 · 창 안 · 창 뒤에 사실이 다르다(실측 2026-10-14 격리 사본: 창 안은 잎 기준 둘 「주의」 ·
# 창 뒤는 「경보 수확 지연」 하나 · 서리는 창과 함께 빠진다). 한 문장을 박아 두면 창이 닫힌 날부터 거짓이 된다 — tests/test_ledger_page_by_phase.py 가 판정으로 다시 잰다
_PHASE = "앞" if today() < _WINDOW_OPEN else ("창" if today() <= _WINDOW_END else "뒤")
# [재검토 L1 · L3 · R1 · R2 · 2026-10-14] 창(_PHASE)은 경보 문장에만 — 답(자재 · 가뭄 · 촬영 · 위험 머리)을 인용하는 문장은 **답이 읽는 칸**(_AT)으로 고른다.
# 둘이 갈리는 날이 창이 열리는 날(경계일은 앞 칸)이다. 과습 · 배수 문장은 위험 경보가 오늘 과습 칸을 보는지(_WET_NOW)로 고른다
_AT, _HARVEST_FROM = stage_today(), harvest_stage_from()
_WET_NOW, _WET_END, _WET_STAGE = wet_now()
