# 세션 스크래치패드에만 있다가 컨테이너와 함께 사라졌다 — 발행자에게 아무도 풀 수 없는 번호를 보였다. 이제 번호마다 무엇 · 어디서 다시 보나가 저장소에 있다
WALK_DOC = ROOT / "docs" / "walk_findings.md"
WALK_GRADES, WALK_OWNERS = ("즉시", "등재", "관찰"), ("세션", "발행자")      # 그 문서 머리의 「급 —」 · 「몫 —」 정의와 같은 말


def walk_rows() -> list[dict[str, str]]:
    """발견 목록 표의 행 — 번호 · 급 · 몫 · 언제부터 · 무엇 · 어디서 · 렌즈 · 상태."""
    keys = ("id", "grade", "owner", "since", "what", "where", "lens", "state")
    rows = []
    # [재재검토 2026-10-14] 행을 번호 꼴(「W-」 · 「**W-」)로 고르면 「*W-44*」 · 「`W-44`」 같은 행이 **말없이** 빠졌다 — 표 구역(「## 표」)의 몸 줄 전부를 행으로 읽고,
    # 꾸밈(* ` _)을 걷은 뒤 번호 꼴이 아니면 멈춘다(빠뜨리지 않는다)
    text = WALK_DOC.read_text(encoding="utf-8")
    head = re.search(r"(?m)^## 표\s*$", text)
    assert head, "발견 목록에 「## 표」 구역이 없다"
    sec = text[head.end():].split("\n## ", 1)[0]
    lines = [ln for ln in sec.splitlines() if ln.strip().startswith("|")]
    assert len(lines) >= 2 and set(lines[1].replace("|", "").strip()) <= set("-: "), "발견 목록 표의 머리 · 구분 줄을 못 찾았다"
    for line in lines[2:]:
        # [재검토 WF-4 · 2026-10-14] 굵게 쓴 「**즉시**」 · 「**열림**」 은 아래 고르기의 같음 비교에서 **말없이** 빠졌다(F36 이 대장 상태 셀에서 고친 꼴) —
        # 꾸밈을 걷고, 급 · 몫 · 상태가 정해진 말이 아니면 멈춘다(빠뜨리지 않는다)
        cells = [c.strip().strip("*`_").strip() for c in line.strip().strip("|").split("|")]
        assert len(cells) == len(keys), f"발견 목록 행의 칸 수가 다르다: {line[:60]}"
        r = dict(zip(keys, cells))
        assert re.fullmatch(r"W-\d+", r["id"]), f"번호 꼴이 다르다: {r['id']!r}"
        assert r["grade"] in WALK_GRADES and r["owner"] in WALK_OWNERS and re.fullmatch(r"열림|고침\(.+\)", r["state"]), \
            f"{r['id']}: 급 · 몫 · 상태가 정해진 말이 아니다 — {r['grade']!r} · {r['owner']!r} · {r['state'][:20]!r} (급 {WALK_GRADES} · 몫 {WALK_OWNERS} · 상태 열림 | 고침(…))"
        rows.append(r)
    assert rows, "발견 목록을 못 읽었다 — 남은 즉시급을 0 으로 말하게 된다"
    assert len({r["id"] for r in rows}) == len(rows), "발견 목록에 같은 번호가 둘이다"
    return rows


_WALK = walk_rows()
